def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        email = (match.group(1) if match else value).strip().lower()

        if email.count("@") != 1:
            return ""

        local, domain = email.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"[^0-9]", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    contacts = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        contacts.append({
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower()
                         in {"y", "yes", "true", "1"},
            "updated": parse_updated(row["updated"]),
            "_index": index,
        })

    # Union-find preserves transitive matches across both matching rules.
    parent = list(range(len(contacts)))
    size = [1] * len(contacts)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(a, b):
        a, b = find(a), find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    emails = {}
    phones_and_names = {}

    for index, contact in enumerate(contacts):
        email = contact["email"]
        if email:
            if email in emails:
                union(index, emails[email])
            else:
                emails[email] = index

        if contact["phone"] and contact["last_name"]:
            key = (contact["phone"], contact["last_name"].casefold())
            if key in phones_and_names:
                union(index, phones_and_names[key])
            else:
                phones_and_names[key] = index

    groups = {}
    for index, contact in enumerate(contacts):
        groups.setdefault(find(index), []).append(contact)

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(contact["_index"] for contact in group),
    )

    result = []
    fields = ("first_name", "last_name", "zip", "email", "phone", "source")

    for group in ordered_groups:
        # Descending preference: manual, newest timestamp, earliest input row.
        preferred = sorted(
            group,
            key=lambda contact: (
                contact["source"] == "manual",
                contact["updated"],
                -contact["_index"],
            ),
            reverse=True,
        )

        person = {
            field: next(
                (contact[field] for contact in preferred if contact[field]),
                "",
            )
            for field in fields
        }
        person["tags"] = ";".join(sorted({
            tag for contact in group for tag in contact["tags"]
        }))
        person["opted_out"] = (
            "Y" if any(contact["opted_out"] for contact in group) else "N"
        )
        person["updated"] = max(
            contact["updated"] for contact in group
        ).strftime("%Y-%m-%d")
        result.append(person)

    return result
